#[test]
fn ledger_scores_match_python() {
    let (_b, l) = ledger_copy("ledger-scores");
    for (as_of, want) in expected()["ledger_scores"].as_object().unwrap() {
        let got = l.scores(Some(dt(as_of)));
        assert_eq!(got.len(), want.as_array().unwrap().len());
        for (g, w) in got.iter().zip(want.as_array().unwrap()) {
            let key = format!("{as_of} {}", g.key());
            assert_eq!(g.skill, s(&w["skill"]), "{key}");
            assert_eq!(g.version, s(&w["version"]), "{key}");
            assert_eq!(g.served, w["served"], "{key}");
            assert_eq!(g.followed, w["followed"], "{key}");
            assert_eq!(g.imported_served, w["imported_served"], "{key}");
            assert_eq!(g.imported_followed, w["imported_followed"], "{key}");
            assert_eq!(g.rank, w["rank"].as_u64().unwrap() as usize, "{key}");
            assert_eq!(g.net_effect_sign, s(&w["net_effect_sign"]), "{key}");
            assert_eq!(g.anti_pattern, w["anti_pattern"].as_bool().unwrap(), "{key}");
            assert_eq!(g.flag, w["flag"].as_str(), "{key}");
            assert_eq!(skmem::pyjson::float_repr(g.net), s(&w["net_repr"]), "net {key}");
            assert_eq!(
                skmem::pyjson::float_repr(g.follow_rate),
                s(&w["follow_rate_repr"]),
                "rate {key}"
            );
        }
    }
}

#[test]
fn ledger_record_bytes_match_python() {
    let ex = expected();
    let d = scratch("ledger-record");
    let base = d.join("base");
    let l = Ledger::new(&base, Some("skap01"));
    for c in ex["ledger_calls"].as_array().unwrap() {
        let r = Record {
            effect: c["effect"].as_str(),
            session: c["session"].as_str().unwrap_or(""),
            at: c["at"].as_str().map(dt),
            event_id: c["event_id"].as_str(),
            source: c["source"].as_str(),
            missing: c["missing"].as_str(),
        };
        l.record(s(&c["skill"]), s(&c["version"]), s(&c["event"]), &r).unwrap();
    }
    // a second record with a known id appends nothing
    l.record(
        "recover-schema",
        "1.2",
        "served",
        &Record {
            session: "s1",
            at: Some(dt("2026-08-13T12:00:00+00:00")),
            event_id: Some(&"a".repeat(32)),
            ..Default::default()
        },
    )
    .unwrap();
    for (name, text) in ex["ledger_files"].as_object().unwrap() {
        let got = fs::read_to_string(base.join("ledger").join(name)).unwrap();
        assert_eq!(got, s(text), "{name}");
    }
    let n = fs::read_dir(base.join("ledger")).unwrap().count();
    assert_eq!(n, ex["ledger_files"].as_object().unwrap().len());
}

#[test]
fn ledger_never_fuses_onto_a_torn_tail() {
    let ex = expected();
    let d = scratch("ledger-torn");
    let base = d.join("base");
    fs::create_dir_all(base.join("ledger")).unwrap();
    fs::write(base.join("ledger/outcomes-skwk02-2026-10.jsonl"), s(&ex["ledger_torn_before"])).unwrap();
    let l = Ledger::new(&base, Some("skwk02"));
    l.record(
        "after-torn",
        "1",
        "served",
        &Record {
            session: "s",
            at: Some(dt("2026-10-11T00:00:00Z")),
            event_id: Some(&"t0".repeat(16)),
            ..Default::default()
        },
    )
    .unwrap();
    let got = fs::read_to_string(base.join("ledger/outcomes-skwk02-2026-10.jsonl")).unwrap();
    assert_eq!(got, s(&ex["ledger_torn_file"]));
    assert!(l.events().iter().any(|e| e.skill == "after-torn"));
}

